package controller;
import dao.UserDAO;import model.User;import util.DBConnection;import util.PasswordHash;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import jakarta.servlet.*;import java.io.IOException;import java.sql.*;
@WebServlet("/change-password") public class ChangePasswordServlet extends HttpServlet{
 protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException,ServletException{if(q.getSession(false)==null||q.getSession(false).getAttribute("user")==null){s.sendRedirect("login.jsp");return;}q.getRequestDispatcher("change-password.jsp").forward(q,s);}
 protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException,ServletException{HttpSession hs=q.getSession(false);User u=hs==null?null:(User)hs.getAttribute("user");if(u==null){s.sendRedirect("login.jsp");return;}String old=q.getParameter("currentPassword"),n=q.getParameter("newPassword"),c=q.getParameter("confirmPassword");if(old==null||n==null||n.length()<8||!n.equals(c)){q.setAttribute("error","New password must be at least 8 characters and both entries must match.");q.getRequestDispatcher("change-password.jsp").forward(q,s);return;}try(Connection db=DBConnection.getConnection();PreparedStatement p=db.prepareStatement("SELECT password FROM users WHERE user_id=?")){p.setInt(1,u.getUserId());try(ResultSet r=p.executeQuery()){if(!r.next()||!(PasswordHash.isHashed(r.getString(1)) ? PasswordHash.verify(old,r.getString(1)) : old.equals(r.getString(1)))){q.setAttribute("error","Current password is incorrect.");q.getRequestDispatcher("change-password.jsp").forward(q,s);return;}}try(PreparedStatement p2=db.prepareStatement("UPDATE users SET password=? WHERE user_id=?")){p2.setString(1,PasswordHash.hash(n));p2.setInt(2,u.getUserId());p2.executeUpdate();}q.setAttribute("message","Password changed successfully.");q.getRequestDispatcher("change-password.jsp").forward(q,s);}catch(SQLException e){throw new ServletException(e);}}
}
